                    <span>Universitas NaraDipa</span> <!-- Teks keterangan berisi "Universitas NaraDipa" -->
                </h1> <!-- Tutup judul utama -->

                <div class="pmblogin-left-text-box"> <!-- Wadah -->
                    <p> <!-- Paragraf -->
