                <div> <!-- Wadah -->
                    <strong>Universitas NaraDipa</strong> <!-- Teks tebal berisi "Universitas NaraDipa" -->
                    <span>Pendaftaran Mahasiswa Baru</span> <!-- Teks keterangan berisi "Pendaftaran Mahasiswa Baru" -->
                </div> <!-- Tutup wadah -->
            </div> <!-- Tutup wadah -->

            <h2>Login</h2> <!-- Judul bagian berisi "Login" -->

            <p class="pmblogin-subtitle"> <!-- Paragraf -->
                Masuk ke akun Anda untuk melanjutkan <!-- Teks paragraf -->
                proses pendaftaran. <!-- Teks paragraf -->
            </p> <!-- Tutup paragraf -->

            <form action="login.php" method="POST"> <!-- Form kirim data (method POST) -->

                <div class="pmblogin-input-group"> <!-- Wadah -->
                    <span class="pmblogin-icon">👤</span> <!-- Teks keterangan berisi "👤" -->
                    <input
                        type="text"
                        name="username"
                        placeholder="Username / Email / No. HP"
                        required
                    > <!-- Input text "username" (wajib diisi) -->
                </div> <!-- Tutup wadah -->


                <div class="pmblogin-input-group"> <!-- Wadah -->
                    <span class="pmblogin-icon">🔒</span> <!-- Teks keterangan berisi "🔒" -->
