                        type="button"
                        class="pmblogin-toggle-eye"
                        onclick="toggleLihatPassword()"
                        id="toggleEyeBtn"
                        title="Lihat/sembunyikan password"
                    > <!-- Tombol untuk menyalin nomor test -->
