                        </option> <!-- Tutup satu pilihan -->

                        <option value="admin"> <!-- Satu pilihan -->
                            Admin <!-- Teks yang ditampilkan di halaman -->
                        </option> <!-- Tutup satu pilihan -->

                    </select> <!-- Tutup kotak pilihan (dropdown) -->
                    <span class="pmblogin-select-arrow">▼</span> <!-- Teks keterangan berisi "▼" -->
                </div> <!-- Tutup wadah -->


                <button
                    type="submit"
                    name="login"
                    class="pmblogin-btn-login"
                > <!-- Tombol kirim form (login) -->
                    Login <!-- Teks pada tombol -->
                </button> <!-- Tutup tombol -->

            </form> <!-- Tutup form -->


            <div class="pmblogin-divider"> <!-- Wadah -->
                atau <!-- Teks yang ditampilkan di halaman -->
            </div> <!-- Tutup wadah -->


            <a href="register.php" class="pmblogin-btn-register"> <!-- Link ke register.php -->
