        </div> <!-- Tutup kotak form login -->

    </div> <!-- Tutup sisi kanan login -->


</div> <!-- Tutup pembungkus kotak login -->

</div> <!-- Tutup halaman login -->


<script> // Awal blok JavaScript

function toggleLihatPassword() // Fungsi toggleLihatPassword: minta konfirmasi (OK/Batal)
{ // Awal blok kode
    const input = document.getElementById('passwordInput'); // Ambil kolom input password
    const btn = document.getElementById('toggleEyeBtn'); // Ambil tombol ikon mata

    if (input.type === 'password') { // Kalau password sedang disembunyikan
        input.type = 'text'; // Tampilkan password sebagai teks biasa
        btn.textContent = '🙈'; // Ganti ikon jadi mata tertutup
    } else { // Kalau browser tidak mendukung:
        input.type = 'password'; // Sembunyikan password lagi
        btn.textContent = '👁️'; // Ganti ikon jadi mata terbuka
    } // Akhir blok kode
} // Akhir blok kode

</script> <!-- Tutup blok JavaScript -->

</body> <!-- Tutup isi halaman (body) -->

</html> <!-- Tutup tag html -->
